manufacturer = value['Manufacturer'].iloc[0].upper() if 'Manufacturer' in value.columns else ''
axis = (params.get('expected_axis') or 'COL').upper()
expect_reversed = params.get('expect_reversed')
if expect_reversed is None:
    expect_reversed = True

if 'InPlanePhaseEncodingDirection' in value.columns:
    pe_dir = str(value['InPlanePhaseEncodingDirection'].iloc[0]).upper()
    if pe_dir != axis:
        raise ValidationError(f"Phase encoding should be along {axis}. Found: {pe_dir}")

if 'SIEMENS' in manufacturer:
    if 'PhaseEncodingDirectionPositive' in value.columns:
        pe_positive = value['PhaseEncodingDirectionPositive'].iloc[0]
        if pe_positive is not None and not pd.isna(pe_positive):
            expected = 0 if expect_reversed else 1
            if int(pe_positive) != expected:
                raise ValidationError(f"Phase encoding polarity mismatch: PhaseEncodingDirectionPositive={int(pe_positive)}, expected {expected}.")
    else:
        raise ValidationWarning('Siemens PhaseEncodingDirectionPositive not found. Cannot verify phase encoding polarity.')
elif 'GE' in manufacturer:
    if 'RectilinearPhaseEncodeReordering' in value.columns:
        pe_reorder = str(value['RectilinearPhaseEncodeReordering'].iloc[0]).upper()
        is_reversed = 'REVERSE' in pe_reorder
        if is_reversed != expect_reversed:
            raise ValidationWarning(f"GE phase encode reordering '{pe_reorder}' does not match the expected polarity.")
    else:
        raise ValidationWarning('GE RectilinearPhaseEncodeReordering not found. Cannot verify phase encoding polarity.')
elif 'PHILIPS' in manufacturer:
    raise ValidationWarning('Philips DICOM does not encode phase encoding polarity. Please verify manually.')

n = value["EchoTime"].dropna().nunique()
exact = params.get("exact_echoes")
if exact is not None:
    if n != exact:
        raise ValidationError(f"Expected exactly {exact} echoes, found {n}.")
else:
    min_n = params.get("min_echoes")
    if min_n is not None and n < min_n:
        raise ValidationError(f"Only {n} echoes; at least {min_n} required.")
    rec = params.get("recommended_echoes")
    if rec is not None and n < rec:
        raise ValidationWarning(f"Found {n} echoes; {rec}+ recommended.")

if "PixelSpacing" in value.columns:
    pixel_spacing = value["PixelSpacing"].iloc[0]
    if isinstance(pixel_spacing, (list, tuple)) and len(pixel_spacing) >= 2:
        avg_spacing = (pixel_spacing[0] + pixel_spacing[1]) / 2
        max_sp = params.get("max_inplane_mm")
        if max_sp is not None and avg_spacing > max_sp:
            raise ValidationError(f"In-plane resolution should be <= {max_sp:g} mm. Found: {avg_spacing:.2f} mm")

